     3→
     4→type Section = {
     5→  id?: string;
     6→  slug: string;
     7→  titleEn: string;
     8→  titleFr: string;
     9→  type: string;
    10→  entryType: string;
    11→  entryIds?: string[];
    12→  order?: number;
    13→  published?: boolean;
    14→};
    15→
    16→export default async function ResumePage({
    17→  params,
    18→}: {
    19→  params: Promise<{ locale: string }>;
    20→}) {
    21→  const { locale } = await params;
    22→
    23→  const safeFetch = async <T,>(promise: Promise<T>, fallback: T): Promise<T> => {
    24→    try {
    25→      return await promise;
    26→    } catch {
    27→      return fallback;
    28→    }
    29→  };
    30→
    31→  const [entries, profile, theme, rawSections] = await Promise.all([
    32→    safeFetch(prisma.resumeEntry.findMany({ orderBy: { order: "asc" } }), []),
    33→    safeFetch(prisma.resumeProfile.findFirst(), null),
    34→    safeFetch(prisma.resumeTheme.findFirst(), null),
    35→    safeFetch(prisma.resumeSection.findMany({ orderBy: { order: "asc" } }), []),
    36→  ]);
    37→
    38→  // Transform sections to match expected type (handle null values)
    39→  const sections: Section[] = rawSections.map((s) => ({
    40→    id: s.id,
    41→    slug: s.slug,
    42→    titleEn: s.titleEn ?? "",
    43→    titleFr: s.titleFr ?? "",
    44→    type: s.type,
    45→    entryType: s.entryType ?? "",
    46→    entryIds: Array.isArray(s.entryIds) ? s.entryIds as string[] : undefined,
    47→    order: s.order,
    48→    published: s.published,
