import { prisma } from "@/lib/prisma";
import { ResumeForm } from "@/components/admin/resume-form";
import { notFound } from "next/navigation";
import type { ResumeEntryCreateFormInput } from "@/lib/validations/schemas";

type ResumeEntryType = ResumeEntryCreateFormInput["type"];

export default async function EditResumeEntryPage({
  params,
}: {
  params: Promise<{ locale: string; id: string }>;
}) {
  const { locale, id } = await params;

  const entry = await prisma.resumeEntry.findUnique({
    where: { id },
  });

  if (!entry) {
    notFound();
  }

  // Transform Prisma entry to form-compatible data
  const formData: Partial<ResumeEntryCreateFormInput> & { id: string } = {
    id: entry.id,
    type: entry.type as ResumeEntryType,
    titleEn: entry.titleEn,
    titleFr: entry.titleFr,
    subtitleEn: entry.subtitleEn ?? undefined,
    subtitleFr: entry.subtitleFr ?? undefined,
    dateRangeEn: entry.dateRangeEn ?? undefined,
    dateRangeFr: entry.dateRangeFr ?? undefined,
    descriptionEn: entry.descriptionEn ?? undefined,
    descriptionFr: entry.descriptionFr ?? undefined,
    value: entry.value ?? undefined,
    link: entry.link ?? undefined,
    published: entry.published,
    order: entry.order,
  };

  return (
    <div className="space-y-6">
      <h1 className="text-3xl font-bold tracking-tight text-admin-text-primary">Edit Resume Entry</h1>
      <ResumeForm locale={locale} initialData={formData} isEditing />
    </div>
  );
}

import { prisma } from "@/lib/prisma";
import { CVEditor } from "@/components/admin/cv/cv-editor";
import type { CVData, CVTheme } from "@/types/cv";

const defaultTheme: CVTheme = {
  primary: "#F73604", // Orange vif (accent unique)
  secondary: "#F73604", // Même accent
  header: "#0B0C12", // Noir
  sidebar: "#F4F5F7", // Gris clair
  surface: "#FFFFFF", // Blanc
  text: "#0B0C12", // Noir
  muted: "#666666", // Gris
  border: "#0B0C12", // Bordure noire
  badge: "#F73604", // Même accent
};

export default async function CVAdminPage({ params }: { params: Promise<{ locale: string }> }) {
  const { locale } = await params;

  const cv = await prisma.cV.findFirst({
    include: {
      sections: {
        orderBy: { order: "asc" },
        include: {
          translations: true,
          items: {
            orderBy: { order: "asc" },
            include: {
              translations: true,
            },
          },
        },
      },
      skills: {
        orderBy: { order: "asc" },
        include: {
          translations: true,
        },
      },
      socialLinks: {
        orderBy: { order: "asc" },
      },
    },
  });

  const profileFallback = await prisma.resumeProfile.findFirst().catch(() => null);

  const transformedCV: CVData | null = cv
    ? {
        id: cv.id,
        fullName: cv.fullName,
        badgeFr: cv.badgeFr,
        badgeEn: cv.badgeEn,
        photo: cv.photo,
        phone: cv.phone,
        email: cv.email,
        website: cv.website,
        location: cv.location,
        linkedInUrl: cv.linkedInUrl,
        headlineFr: cv.headlineFr,
        headlineEn: cv.headlineEn,
        bioFr: cv.bioFr,
        bioEn: cv.bioEn,
        layout: cv.layout,
        accentColor:
          cv.accentColor ||
          (cv.theme as { primary?: string } | null)?.primary ||
          defaultTheme.primary,
        showPhoto: cv.showPhoto,
        theme: (cv as { theme?: unknown }).theme as CVTheme | null,
        sections: cv.sections.map((section) => ({
          id: section.id,
          type: section.type,
          icon: section.icon,
          color: section.color,
          placement: section.placement,
          layoutType: section.layoutType,
          order: section.order,
          isActive: section.isActive,
          translations: section.translations.map((t) => ({
            locale: t.locale,
            title: t.title,
          })),
          items: section.items.map((item) => ({
            id: item.id,
            startDate: item.startDate?.toISOString() ?? null,
            endDate: item.endDate?.toISOString() ?? null,
            isCurrent: item.isCurrent,
            order: item.order,
            isActive: item.isActive,
            translations: item.translations.map((t) => ({
              locale: t.locale,
              title: t.title,
              subtitle: t.subtitle,
              location: t.location,
              description: t.description,
            })),
          })),
        })),
        skills: cv.skills.map((skill) => ({
          id: skill.id,
          category: skill.category,
          level: skill.level,
          showAsBar: skill.showAsBar,
          order: skill.order,
          isActive: skill.isActive,
          translations: skill.translations.map((t) => ({
            locale: t.locale,
            name: t.name,
          })),
        })),
        socialLinks: cv.socialLinks.map((link) => ({
          id: link.id,
          platform: link.platform,
          url: link.url,
          label: link.label,
          order: link.order,
        })),
      }
    : profileFallback
      ? {
          sections: [],
          skills: [],
          socialLinks: [],
          fullName: profileFallback.name,
          badgeFr: profileFallback.roleFr,
          badgeEn: profileFallback.roleEn,
          headlineFr: profileFallback.headlineFr,
          headlineEn: profileFallback.headlineEn,
          email: profileFallback.email,
          phone: profileFallback.phone,
          location: profileFallback.location,
          website: profileFallback.website,
          photo: profileFallback.photo,
          accentColor: defaultTheme.primary,
          showPhoto: true,
          layout: "creative",
          theme: defaultTheme,
        }
      : null;

  return (
    <div className="space-y-6 pb-10">
      <div className="flex flex-col gap-2">
        <h1 className="text-3xl font-bold text-foreground">Éditeur de CV</h1>
        <p className="text-foreground/50">
          Gérez le contenu du CV et prévisualisez le PDF en temps réel.
        </p>
      </div>
      <CVEditor initialData={transformedCV} locale={locale} />
    </div>
  );
}

